/**
 * Share-link dictionaries, version 1. FROZEN: a link compressed against a dictionary opens only with
 * exactly the same text, so never edit, reorder or remove anything here, and never derive it from the
 * live blueprints. To improve compression later, append new dictionaries; a link names its own by index.
 * `graphFeedback.test` pins each dictionary's SHA-256.
 *
 * Dictionary 0 is general: every distinct line of the ten starter graphs as of 2026-10-21, then the lines
 * every graph file repeats, most common last (deflate refers to nearby text more cheaply). Dictionaries
 * 1 to 10 append one starter graph each, so a graph edited from that starter costs only its changes.
 */

/** Deflate looks back at most this far, so a dictionary longer than this is wasted. */
export const SHARE_DICTIONARY_WINDOW = 32_768;

const GENERAL = "name: parallel-system-audit\ndescription: Splits a goal into 4 parallel workers, verifies with fresh context, and synthesizes.\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: 1. GOAL\n    - id: splitter\n      type: orchestrator\n      label: 2. SPLIT\n      model: sonnet\n      tools: [Read]\n    - id: worker_research\n      type: worker\n      label: \"3. WORKER 1: Research\"\n      model: haiku\n      tools: [Read, Grep, Glob, WebSearch, WebFetch]\n    - id: worker_compare\n      label: \"3. WORKER 2: Compare\"\n      tools: [Read, Grep, Glob, WebSearch]\n    - id: worker_check\n      label: \"3. WORKER 3: Check\"\n      tools: [Read, Grep, Glob, Bash]\n    - id: worker_gaps\n      label: \"3. WORKER 4: Find Gaps\"\n      tools: [Read, Grep, Glob]\n    - id: verifier\n      type: verifier\n      label: 4. VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      gate: Every kept claim cites concrete evidence and no two workers contradict each other.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: 5 & 6. MERGE & FINAL ANSWER\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n        - worker_research\n        - worker_compare\n        - worker_check\n        - worker_gaps\n      contract: subtask_json\n    - from:\n      to: verifier\n      contract: findings_array\n    - from: verifier\n      to: merger\n      contract: verified_payload\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task in one or two sentences.\n  findings_array:\n    format: markdown\n    description: A numbered list of findings, each with its evidence (file, line, quote or URL) and a confidence of high, medium or low.\n  verified_payload:\n    description: Only the claims that passed verification, then a short list of rejected claims with the reason.\n# Node Prompts & Edge Contracts\n## @node: splitter\nYou are the Orchestrator. Take the user's goal and break it into 4 distinct tasks.\nThe goal:\n{{goal}}\nOutput strictly as JSON with keys: `worker_research`, `worker_compare`, `worker_check`, `worker_gaps`.\n## @node: worker_research\nFocus ONLY on deep research for: {{splitter.worker_research}}\nReturn findings with exact citations.\n## @node: worker_compare\nFocus ONLY on comparing alternatives and trade-offs for: {{splitter.worker_compare}}\n## @node: worker_check\nFocus ONLY on checking technical constraints and correctness for: {{splitter.worker_check}}\n## @node: worker_gaps\nFocus ONLY on finding missing edge cases and blind spots for: {{splitter.worker_gaps}}\n## @node: verifier\n**CRITICAL: FRESH CONTEXT MODE.**\nYou only see the raw outputs from the 4 workers. You do NOT see their reasoning chain.\nAudit every claim below for hallucinations, bias, or weak evidence. Reject unverified claims.\nOriginal goal: {{goal}}\nWorker outputs:\n{{workers.output}}\n## @node: merger\nCombine the verified findings below into one clear, actionable report.\n{{verifier.output}}\nname: ship-a-change\ndescription: Implements a change in a loop on the test suite, reviews the diff in parallel, gates it in a fresh context, and opens a pull request after one approval.\nexperience:\n  max_lessons: 20\n      label: CHANGE REQUEST\n    - id: plan\n      label: PLAN\n    - id: implement\n      label: IMPLEMENT (loops on tests)\n      tools: [Read, Grep, Glob, Edit, Write, Bash]\n      check: npm test\n      max_retries: 2\n      risk: wide\n    - id: diff\n      type: code\n      label: COLLECT DIFF\n      run: git diff --stat && git diff\n    - id: review_correctness\n      label: \"REVIEW: Correctness\"\n    - id: review_security\n      label: \"REVIEW: Security\"\n    - id: gate\n      label: GATE (Fresh Context)\n      gate: No blocking finding is left open, and every finding cites a line of the diff.\n      retry_target: implement\n    - id: approve\n      type: approval\n      label: APPROVE PULL REQUEST\n    - id: publish\n      type: agent\n      label: OPEN PULL REQUEST\n      tools: [Bash]\n      risk: irreversible\n      on_fail: stop\n      to: plan\n    - from: plan\n      to: implement\n      contract: change_plan\n    - from: implement\n      to: diff\n    - from: diff\n        - review_correctness\n        - review_security\n        - gate\n      contract: diff_text\n      to: gate\n      contract: review_findings\n    - from: gate\n        - approve\n        - publish\n      contract: verdict\n    - from: approve\n      to: publish\n  change_plan:\n    description: The files to change, what changes in each, and the tests that prove it.\n  diff_text:\n    format: text\n    description: The output of git diff, unchanged.\n  review_findings:\n    description: A numbered list; each finding cites a file and line of the diff and says blocking or minor.\n  verdict:\n    description: PASS or FAIL, the findings kept with their evidence, and a three-line summary of the change.\n## @node: plan\nRead the code this request touches and write a short plan: the files to change, what changes in each, and the tests to add or update.\nThe request:\n## @node: implement\nImplement this plan. Change only the files it names; add or update the tests it lists.\n{{plan.output}}\nReturn a short summary of what you changed.\n## @node: review_correctness\nReview ONLY correctness: logic errors, missed edge cases, broken contracts and tests that do not test the change.\n{{diff.output}}\n## @node: review_security\nReview ONLY security: injection, missing authorization, secrets, unsafe input handling.\n## @node: gate\nYou see only the diff and the two reviews, not how the change was made. Keep the findings that the diff supports, drop the rest, and decide whether anything blocking is left.\nDiff:\nReviews:\n{{review_correctness.output}}\n{{review_security.output}}\n## @node: approve\nShow the verdict and the diff summary, then ask: open a pull request with this change?\n## @node: publish\nThe user approved: {{approve.output}}\nCommit the change on a new branch, push it, and open a pull request. Use the summary in this verdict as its description:\n{{gate.output}}\nname: review-each-file\ndescription: Lists the files a change touches, reviews each one in its own fresh-context run, merges the findings and gates them before reporting.\nspec: skill-graph/2\nhandoff: file\n      label: CHANGE TO REVIEW\n    - id: scope\n      label: LIST THE FILES\n      tools: [Read, Grep, Glob, \"Bash(git diff:*)\"]\n      output_format: json\n    - id: review_file\n      label: REVIEW EACH FILE\n      foreach: scope.files\n      max_parallel: 6\n      max_items: 40\n    - id: merge\n      label: MERGE FINDINGS\n      gate: Every blocking finding names a file and line that exist, and no finding is listed twice.\n      retry_target: merge\n      to: scope\n    - from: scope\n      to: review_file\n      contract: file_list\n    - from: review_file\n      to: merge\n      contract: file_reviews\n    - from: merge\n      contract: findings\n  file_list:\n    description: \"{ files: the changed paths to review, focus: one sentence on what the change is for }\"\n    required: [files, focus]\n  file_reviews:\n    description: One entry per file, in file order; each lists its findings with line, severity and evidence.\n  findings:\n    description: Findings grouped by severity (blocking, should fix, nit); each names the file and line.\n## @node: scope\nFind the files this change touches (run git diff --name-only for the range the user gives, or against the main branch). Leave out generated files, lockfiles and binaries.\nThe change:\nReturn JSON: {\"files\": [the paths], \"focus\": \"one sentence on what the change is for\"}.\n## @node: review_file\nReview this one file as part of a change whose purpose is: {{scope.focus}}\nFile: {{item}}\nRead the file and its diff. Report only real problems in this file: bugs, missed edge cases, security issues, and code that does not do what the change is for. For each give the line, a severity (blocking, should fix, nit) and the evidence. If the file is fine, say so in one line.\n## @node: merge\nMerge these per-file reviews into one list. Drop duplicates, group by severity (blocking first), and keep the file, line and evidence of each finding.\n{{review_file.output}}\nYou see only the merged findings, not how they were produced. Open each file and line a blocking finding names and check that it exists and says what the finding claims.\n{{merge.output}}\nname: pr-review-graph\ndescription: Reviews a pull request with four parallel specialists, filters false positives in a fresh context, and writes prioritized PR comments.\n      label: PULL REQUEST (diff or link)\n      label: SPLIT\n      tools:\n        - Read\n      label: Security & Auth\n        - Grep\n        - Glob\n        - Bash\n    - id: review_performance\n      label: Performance & Memory\n    - id: review_architecture\n      label: Architecture & Style\n    - id: review_tests\n      label: Test Coverage\n      label: VERIFIER (Fresh Context)\n      gate: Every kept finding points at a file and line in the diff.\n      label: FINAL ANSWER\n        - review_performance\n        - review_architecture\n        - review_tests\n      contract: verified_findings\n    description: One key per worker id; each value is that worker's task.\n    description: A numbered list; every item has its evidence and a confidence of high, medium or low.\n  verified_findings:\n    description: Only the items that passed verification, then the rejected ones with the reason.\nYou are the review lead. Read the pull request and give each reviewer the files and concerns that matter for their specialty.\nInput:\nOutput strictly as JSON with one key per worker: `review_security`, `review_performance`, `review_architecture`, `review_tests`. Each value is the exact task for that worker.\nReview ONLY for security: injection, authn/authz gaps, secrets, unsafe deserialization, SSRF, missing input validation.\nYour task: {{splitter.review_security}}\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n## @node: review_performance\nReview ONLY for performance: N+1 queries, unbounded loops or payloads, leaks, blocking calls on hot paths, missing caching.\nYour task: {{splitter.review_performance}}\n## @node: review_architecture\nReview ONLY for architecture: layering violations, duplicated logic, naming, consistency with existing patterns in the codebase.\nYour task: {{splitter.review_architecture}}\n## @node: review_tests\nReview ONLY test coverage: untested branches, missing edge cases, brittle or meaningless assertions.\nYour task: {{splitter.review_tests}}\nYou are an independent auditor. Re-check each finding against the diff itself and remove false positives.\nYou only see the raw worker outputs below, not their reasoning. Drop any claim without concrete evidence, merge duplicates, and mark what you rejected and why.\nOriginal input: {{goal}}\nWrite the final review as prioritized PR comments (blocking, should fix, nit). Each comment names the file and line and says what to change.\nname: rfc-discovery-graph\ndescription: Explores a proposal from four angles in parallel, red-teams unstated assumptions in a fresh context, and drafts an RFC.\n      label: PROPOSAL\n    - id: feasibility\n      label: Feasibility Study\n        - WebSearch\n        - WebFetch\n    - id: prior_art\n      label: Prior Art\n    - id: interface_design\n      label: Interface / DX\n    - id: failure_modes\n      label: Failure Modes\n      gate: No kept claim rests on an unstated assumption.\n        - feasibility\n        - prior_art\n        - interface_design\n        - failure_modes\n      contract: research_notes\n      contract: verified_notes\n  research_notes:\n  verified_notes:\nYou are the RFC editor. Turn the proposal into four focused research questions.\nOutput strictly as JSON with one key per worker: `feasibility`, `prior_art`, `interface_design`, `failure_modes`. Each value is the exact task for that worker.\n## @node: feasibility\nAssess ONLY feasibility: effort, dependencies, migration path and the hardest technical risk.\nYour task: {{splitter.feasibility}}\n## @node: prior_art\nSurvey ONLY prior art: existing tools, competitors and published approaches, with what each gets right and wrong.\nYour task: {{splitter.prior_art}}\n## @node: interface_design\nDesign ONLY the interface: API or CLI shape, configuration, error messages and the first five minutes of use.\nYour task: {{splitter.interface_design}}\n## @node: failure_modes\nFind ONLY failure modes: what breaks at scale, under bad input, during partial rollout or rollback.\nYour task: {{splitter.failure_modes}}\nYou are a red-team reviewer. List the unstated assumptions behind each claim and reject claims that rest on them.\nWrite a production RFC in Markdown: Summary, Motivation, Proposal, Alternatives considered, Risks, Open questions.\nname: bug-triaging-graph\ndescription: Triages a bug report with four parallel investigators, re-checks the evidence in a fresh context, and writes a root-cause diagnosis with a test plan.\n      label: BUG REPORT\n    - id: stack_trace\n      label: Stack Trace Analyzer\n    - id: logs_metrics\n      label: Log / Metric Correlator\n    - id: commits\n      label: Commit Inspector\n    - id: repro\n      label: Minimal Repro Builder\n      gate: At least one hypothesis is connected to the symptom by evidence, and the repro reproduces it.\n        - stack_trace\n        - logs_metrics\n        - commits\n        - repro\n      contract: hypotheses\n      contract: root_cause\n  hypotheses:\n  root_cause:\nYou are the triage lead. Split the bug report into four investigation tasks.\nOutput strictly as JSON with one key per worker: `stack_trace`, `logs_metrics`, `commits`, `repro`. Each value is the exact task for that worker.\n## @node: stack_trace\nAnalyze ONLY the stack trace and error: the failing frame, the inputs that reach it, and why it throws.\nYour task: {{splitter.stack_trace}}\n## @node: logs_metrics\nCorrelate ONLY logs and metrics: when it started, what changed at that time, and which users or requests are affected.\nYour task: {{splitter.logs_metrics}}\n## @node: commits\nInspect ONLY recent commits and config changes that touch the failing path, and rank them by likelihood.\nYour task: {{splitter.commits}}\n## @node: repro\nBuild ONLY a minimal reproduction: the smallest steps or script that trigger the bug.\nYour task: {{splitter.repro}}\nYou are an independent debugger. Check that the evidence actually connects each hypothesis to the symptom; reject the rest.\nWrite the diagnosis: root cause, evidence, fix, and a test plan that reproduces the bug before the fix and passes after it.\nname: research-report\ndescription: Researches a question from four angles in parallel, fact-checks every claim against its source in a fresh context, and writes a sourced report.\n      label: RESEARCH QUESTION\n    - id: sources\n      label: Primary Sources\n    - id: figures\n      label: Figures & Data\n    - id: counterpoints\n      label: Counterpoints\n    - id: open_questions\n      label: Open Questions\n      gate: Every kept claim names a source that says it, and every figure has a date.\n        - sources\n        - figures\n        - counterpoints\n        - open_questions\n      contract: research_findings\n      contract: checked_findings\n  research_findings:\n    description: A numbered list of claims; every claim has its source, a short quote and a confidence of high, medium or low.\n  checked_findings:\n    description: Only the claims a cited source supports, then the rejected claims with the reason.\nYou are the research lead. Turn the question into four research tasks, one per angle, each saying what to look for and how recent it must be.\nOutput strictly as JSON with one key per worker: `sources`, `figures`, `counterpoints`, `open_questions`. Each value is the exact task for that worker.\n## @node: sources\nFind ONLY primary sources: official documents, papers, datasets and first-hand accounts, with what each one says.\nYour task: {{splitter.sources}}\nReturn findings as a numbered list. For each one give the source (title and URL), what it says in a short quote, and a confidence of high, medium or low.\n## @node: figures\nCollect ONLY figures: statistics, dates, prices and measurements, each with where it comes from and how recent it is.\nYour task: {{splitter.figures}}\n## @node: counterpoints\nLook ONLY for disagreement: credible sources that contradict the obvious answer, and the reasons they give.\nYour task: {{splitter.counterpoints}}\n## @node: open_questions\nFind ONLY what is unknown or disputed: gaps in the evidence and claims that nobody has checked.\nYour task: {{splitter.open_questions}}\nYou are a fact-checker. Check each claim against the source it cites; reject claims whose source does not say it or is not named.\nWrite the research report in Markdown: the answer in two sentences, Key findings with their sources, Where sources disagree, Open questions, and a list of Sources.\nname: write-an-article\ndescription: Plans an article, post or newsletter from four angles in parallel, has an editor check the notes in a fresh context, and writes the draft.\n      label: BRIEF (topic, audience, length, voice)\n    - id: angle\n      label: Angle & Headline\n    - id: outline\n      label: Outline\n    - id: facts\n      label: Facts & Quotes\n    - id: reader\n      label: Reader\n      gate: Every fact kept has a source, and the angle and outline match the brief's audience and length.\n        - angle\n        - outline\n        - facts\n        - reader\n      contract: content_notes\n      contract: approved_notes\n  content_notes:\n    description: A numbered list of notes, each marked with its source or as opinion.\n  approved_notes:\n    description: The notes that passed the edit, then the cut ones with the reason.\nYou are the managing editor. Read the brief and give each writer the part of the piece they prepare, with the audience and length in mind.\nOutput strictly as JSON with one key per worker: `angle`, `outline`, `facts`, `reader`. Each value is the exact task for that worker.\n## @node: angle\nWork ONLY on the angle: three possible headlines with a hook for each, and which one fits the audience best and why.\nYour task: {{splitter.angle}}\nReturn your notes as a numbered list. Mark each note with the source it rests on, or with \"opinion\" when it rests on none.\n## @node: outline\nWrite ONLY the outline: the sections in order, the point of each one, and where examples go.\nYour task: {{splitter.outline}}\n## @node: facts\nGather ONLY the facts the piece needs: claims, figures and quotes, each with its source.\nYour task: {{splitter.facts}}\n## @node: reader\nThink ONLY about the reader: what they already know, the questions they will ask, and the jargon to avoid.\nYour task: {{splitter.reader}}\nYou are the editor. Check each note for accuracy and for fit with the brief.\nYou only see the raw worker outputs below, not their reasoning. Cut every factual note without a source and every note off the brief, merge duplicates, and list what you cut and why.\nWrite the piece from the approved notes: the headline, a hook paragraph, the sections of the outline, and a closing line. Use only facts from the notes, in the voice and length the brief asks for.\nname: analyze-a-dataset\ndescription: \"Analyzes a CSV or table: profiling, cleaning rules, answers and sanity checks run in parallel, every figure is re-checked in a fresh context, then a data report.\"\n      label: DATA FILE + QUESTIONS\n    - id: profile\n      label: Profile\n    - id: cleaning\n      label: Cleaning Rules\n    - id: analysis\n      label: Analysis\n    - id: sanity\n      label: Sanity Checks\n      gate: Every kept figure says how it was computed and matches the data on a spot check.\n        - profile\n        - cleaning\n        - analysis\n        - sanity\n      contract: data_findings\n      contract: checked_figures\n  data_findings:\n    description: A numbered list; every figure has how it was computed and a confidence of high, medium or low.\n  checked_figures:\n    description: Only the figures that matched the data on a spot check, then the rejected ones with the reason.\nYou are the analysis lead. Read the file path and the questions, and give each analyst their part of the work on that file.\nOutput strictly as JSON with one key per worker: `profile`, `cleaning`, `analysis`, `sanity`. Each value is the exact task for that worker.\n## @node: profile\nProfile ONLY the data: columns, types, row count, missing values, duplicates and outliers. Compute every figure; never estimate it.\nYour task: {{splitter.profile}}\nReturn findings as a numbered list. For each one give the figure, how you got it (the command, formula or rows it rests on) and a confidence of high, medium or low. Never change the data file.\n## @node: cleaning\nPropose ONLY cleaning rules: how to fix types, missing values, duplicates and bad rows, with how many rows each rule touches.\nYour task: {{splitter.cleaning}}\n## @node: analysis\nAnswer ONLY the questions in the task with the data: each figure, and the command or formula that produced it.\nYour task: {{splitter.analysis}}\n## @node: sanity\nCheck ONLY whether the data can be trusted: totals that should add up, impossible values, and gaps in time or coverage.\nYour task: {{splitter.sanity}}\nYou are a data reviewer. Spot-check each figure against the file itself; reject figures you cannot trace back to the data.\nWrite the data report: the answers with their figures, the cleaning steps to apply in order, and the caveats a reader must know.\nname: design-an-app\ndescription: \"Designs an app from an idea: users, scope, screens and data model in parallel, a fresh-context product review that makes them fit together, then a product spec.\"\n      label: APP IDEA\n    - id: users\n      label: Users & Stories\n    - id: features\n      label: Features & Scope\n    - id: screens\n      label: Screens & Flows\n    - id: data_model\n      label: Data Model\n      gate: Every first-version feature maps to a user story, a screen and the data it needs.\n        - users\n        - features\n        - screens\n        - data_model\n      contract: design_proposals\n      contract: approved_design\n  design_proposals:\n    description: A numbered list of proposals, each with the user need it serves and a confidence of high, medium or low.\n  approved_design:\n    description: The proposals that fit together, then the cut ones with the reason.\nYou are the product lead. Read the idea and give each designer their part of the app, with the constraints the idea states.\nOutput strictly as JSON with one key per worker: `users`, `features`, `screens`, `data_model`. Each value is the exact task for that worker.\n## @node: users\nWork ONLY on users: who they are, the jobs they need the app for, and the three most important user stories.\nYour task: {{splitter.users}}\nReturn your proposals as a numbered list. For each one give the user need it serves and a confidence of high, medium or low.\n## @node: features\nScope ONLY the features: the smallest useful first version, what waits for later, and why.\nYour task: {{splitter.features}}\n## @node: screens\nDesign ONLY the screens and flows: each screen, what it shows, and how the user moves between them, with empty and error states.\nYour task: {{splitter.screens}}\n## @node: data_model\nDesign ONLY the data: entities, fields and relationships, and the outside services the app needs.\nYour task: {{splitter.data_model}}\nYou are a product reviewer. Check that the proposals fit together: every screen serves a user story, every feature has a screen, and the data model holds what the screens show.\nYou only see the raw worker outputs below, not their reasoning. Cut proposals that serve no stated user need, settle conflicts between them, and list what you cut and why.\nWrite the product spec in Markdown: Problem, Users and stories, First version scope, Screens and flows, Data model, Open questions.\n## @node: verifier\nOriginal input: {{goal}}\nWorker outputs:\n{{workers.output}}\n{{verifier.output}}\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\nReturn a JSON object with \nReturn a numbered list of \nReturn a Markdown \nThe request:\n{{goal}}\nYour task:\n{{plan.\n---\nname: \ndescription: \nspec: skill-graph/2\nhandoff: file\nexperience:\n  max_lessons: 20\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: request\n      type: input\n      label: REQUEST\n    - id: goal\n      type: input\n      label: GOAL\n    - id: plan\n      type: orchestrator\n      label: PLAN\n      model: sonnet\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - WebSearch\n        - WebFetch\n        - Bash\n        - Edit\n        - Write\n      output_format: json\n      foreach: plan.files\n      max_parallel: 4\n      max_items: 20\n      probe: 3\n      handoff: file\n      risk: wide\n      risk: irreversible\n      check: npm test\n      run: npm test\n    - id: approve\n      type: approval\n      label: APPROVE\n    - id: tests\n      type: code\n      label: TESTS\n      retry_target: implement\n    - id: report\n      type: synthesizer\n      label: REPORT\n      model: sonnet\n    - id: worker\n      type: worker\n      label: WORKER\n      model: haiku\n    - id: verify\n      type: verifier\n      label: VERIFY\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: Every \n      on_fail: retry\n      max_retries: 1\n  edges:\n    - from: request\n      to: plan\n    - from: goal\n      to: \n    - from: plan\n      to:\n        - \n      contract: \ncontracts:\n  plan_tasks:\n    format: json\n    description: One key per step id; each value is that step's task in one or two sentences.\n    format: markdown\n    format: text\n    description: \n    required:\n      - \n    check: \nlayout:\n  positions:\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: ";

/** The starter graphs as they were on 2026-10-21 (not the live ones, which may change). */
const STARTERS: readonly string[] = [
  "---\nname: parallel-system-audit\ndescription: Splits a goal into 4 parallel workers, verifies with fresh context, and synthesizes.\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: 1. GOAL\n    - id: splitter\n      type: orchestrator\n      label: 2. SPLIT\n      model: sonnet\n      tools: [Read]\n    - id: worker_research\n      type: worker\n      label: \"3. WORKER 1: Research\"\n      model: haiku\n      tools: [Read, Grep, Glob, WebSearch, WebFetch]\n    - id: worker_compare\n      type: worker\n      label: \"3. WORKER 2: Compare\"\n      model: haiku\n      tools: [Read, Grep, Glob, WebSearch]\n    - id: worker_check\n      type: worker\n      label: \"3. WORKER 3: Check\"\n      model: haiku\n      tools: [Read, Grep, Glob, Bash]\n    - id: worker_gaps\n      type: worker\n      label: \"3. WORKER 4: Find Gaps\"\n      model: haiku\n      tools: [Read, Grep, Glob]\n    - id: verifier\n      type: verifier\n      label: 4. VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools: [Read, Grep, Glob]\n      gate: Every kept claim cites concrete evidence and no two workers contradict each other.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: 5 & 6. MERGE & FINAL ANSWER\n      model: sonnet\n      tools: [Read]\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - worker_research\n        - worker_compare\n        - worker_check\n        - worker_gaps\n      contract: subtask_json\n    - from:\n        - worker_research\n        - worker_compare\n        - worker_check\n        - worker_gaps\n      to: verifier\n      contract: findings_array\n    - from: verifier\n      to: merger\n      contract: verified_payload\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task in one or two sentences.\n  findings_array:\n    format: markdown\n    description: A numbered list of findings, each with its evidence (file, line, quote or URL) and a confidence of high, medium or low.\n  verified_payload:\n    format: markdown\n    description: Only the claims that passed verification, then a short list of rejected claims with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the Orchestrator. Take the user's goal and break it into 4 distinct tasks.\n\nThe goal:\n{{goal}}\n\nOutput strictly as JSON with keys: `worker_research`, `worker_compare`, `worker_check`, `worker_gaps`.\n\n## @node: worker_research\nFocus ONLY on deep research for: {{splitter.worker_research}}\nReturn findings with exact citations.\n\n## @node: worker_compare\nFocus ONLY on comparing alternatives and trade-offs for: {{splitter.worker_compare}}\n\n## @node: worker_check\nFocus ONLY on checking technical constraints and correctness for: {{splitter.worker_check}}\n\n## @node: worker_gaps\nFocus ONLY on finding missing edge cases and blind spots for: {{splitter.worker_gaps}}\n\n## @node: verifier\n**CRITICAL: FRESH CONTEXT MODE.**\nYou only see the raw outputs from the 4 workers. You do NOT see their reasoning chain.\nAudit every claim below for hallucinations, bias, or weak evidence. Reject unverified claims.\n\nOriginal goal: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nCombine the verified findings below into one clear, actionable report.\n\n{{verifier.output}}\n",
  "---\nname: ship-a-change\ndescription: Implements a change in a loop on the test suite, reviews the diff in parallel, gates it in a fresh context, and opens a pull request after one approval.\nspec: skill-graph/1\nexperience:\n  max_lessons: 20\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: CHANGE REQUEST\n    - id: plan\n      type: orchestrator\n      label: PLAN\n      model: sonnet\n      tools: [Read, Grep, Glob]\n    - id: implement\n      type: worker\n      label: IMPLEMENT (loops on tests)\n      model: sonnet\n      tools: [Read, Grep, Glob, Edit, Write, Bash]\n      check: npm test\n      on_fail: retry\n      max_retries: 2\n      risk: wide\n    - id: diff\n      type: code\n      label: COLLECT DIFF\n      run: git diff --stat && git diff\n    - id: review_correctness\n      type: worker\n      label: \"REVIEW: Correctness\"\n      isolated_context: true\n      model: haiku\n      tools: [Read, Grep, Glob]\n    - id: review_security\n      type: worker\n      label: \"REVIEW: Security\"\n      isolated_context: true\n      model: haiku\n      tools: [Read, Grep, Glob]\n    - id: gate\n      type: verifier\n      label: GATE (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools: [Read, Grep, Glob]\n      gate: No blocking finding is left open, and every finding cites a line of the diff.\n      on_fail: retry\n      max_retries: 2\n      retry_target: implement\n    - id: approve\n      type: approval\n      label: APPROVE PULL REQUEST\n    - id: publish\n      type: agent\n      label: OPEN PULL REQUEST\n      model: haiku\n      tools: [Bash]\n      risk: irreversible\n      on_fail: stop\n  edges:\n    - from: goal\n      to: plan\n    - from: plan\n      to: implement\n      contract: change_plan\n    - from: implement\n      to: diff\n    - from: diff\n      to:\n        - review_correctness\n        - review_security\n        - gate\n      contract: diff_text\n    - from:\n        - review_correctness\n        - review_security\n      to: gate\n      contract: review_findings\n    - from: gate\n      to:\n        - approve\n        - publish\n      contract: verdict\n    - from: approve\n      to: publish\ncontracts:\n  change_plan:\n    format: markdown\n    description: The files to change, what changes in each, and the tests that prove it.\n  diff_text:\n    format: text\n    description: The output of git diff, unchanged.\n  review_findings:\n    format: markdown\n    description: A numbered list; each finding cites a file and line of the diff and says blocking or minor.\n  verdict:\n    format: markdown\n    description: PASS or FAIL, the findings kept with their evidence, and a three-line summary of the change.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: plan\nRead the code this request touches and write a short plan: the files to change, what changes in each, and the tests to add or update.\n\nThe request:\n{{goal}}\n\n## @node: implement\nImplement this plan. Change only the files it names; add or update the tests it lists.\n\n{{plan.output}}\n\nReturn a short summary of what you changed.\n\n## @node: review_correctness\nReview ONLY correctness: logic errors, missed edge cases, broken contracts and tests that do not test the change.\n\n{{diff.output}}\n\n## @node: review_security\nReview ONLY security: injection, missing authorization, secrets, unsafe input handling.\n\n{{diff.output}}\n\n## @node: gate\nYou see only the diff and the two reviews, not how the change was made. Keep the findings that the diff supports, drop the rest, and decide whether anything blocking is left.\n\nDiff:\n{{diff.output}}\n\nReviews:\n{{review_correctness.output}}\n\n{{review_security.output}}\n\n## @node: approve\nShow the verdict and the diff summary, then ask: open a pull request with this change?\n\n## @node: publish\nThe user approved: {{approve.output}}\n\nCommit the change on a new branch, push it, and open a pull request. Use the summary in this verdict as its description:\n{{gate.output}}\n",
  "---\nname: review-each-file\ndescription: Lists the files a change touches, reviews each one in its own fresh-context run, merges the findings and gates them before reporting.\nspec: skill-graph/2\nhandoff: file\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: CHANGE TO REVIEW\n    - id: scope\n      type: orchestrator\n      label: LIST THE FILES\n      model: sonnet\n      tools: [Read, Grep, Glob, \"Bash(git diff:*)\"]\n      output_format: json\n    - id: review_file\n      type: worker\n      label: REVIEW EACH FILE\n      isolated_context: true\n      model: haiku\n      tools: [Read, Grep, Glob]\n      foreach: scope.files\n      max_parallel: 6\n      max_items: 40\n    - id: merge\n      type: synthesizer\n      label: MERGE FINDINGS\n      model: sonnet\n      tools: [Read]\n    - id: gate\n      type: verifier\n      label: GATE (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools: [Read, Grep, Glob]\n      gate: Every blocking finding names a file and line that exist, and no finding is listed twice.\n      on_fail: retry\n      max_retries: 1\n      retry_target: merge\n  edges:\n    - from: goal\n      to: scope\n    - from: scope\n      to: review_file\n      contract: file_list\n    - from: review_file\n      to: merge\n      contract: file_reviews\n    - from: merge\n      to: gate\n      contract: findings\ncontracts:\n  file_list:\n    format: json\n    description: \"{ files: the changed paths to review, focus: one sentence on what the change is for }\"\n    required: [files, focus]\n  file_reviews:\n    format: json\n    description: One entry per file, in file order; each lists its findings with line, severity and evidence.\n  findings:\n    format: markdown\n    description: Findings grouped by severity (blocking, should fix, nit); each names the file and line.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: scope\nFind the files this change touches (run git diff --name-only for the range the user gives, or against the main branch). Leave out generated files, lockfiles and binaries.\n\nThe change:\n{{goal}}\n\nReturn JSON: {\"files\": [the paths], \"focus\": \"one sentence on what the change is for\"}.\n\n## @node: review_file\nReview this one file as part of a change whose purpose is: {{scope.focus}}\n\nFile: {{item}}\n\nRead the file and its diff. Report only real problems in this file: bugs, missed edge cases, security issues, and code that does not do what the change is for. For each give the line, a severity (blocking, should fix, nit) and the evidence. If the file is fine, say so in one line.\n\n## @node: merge\nMerge these per-file reviews into one list. Drop duplicates, group by severity (blocking first), and keep the file, line and evidence of each finding.\n\n{{review_file.output}}\n\n## @node: gate\nYou see only the merged findings, not how they were produced. Open each file and line a blocking finding names and check that it exists and says what the finding claims.\n\n{{merge.output}}\n",
  "---\nname: pr-review-graph\ndescription: Reviews a pull request with four parallel specialists, filters false positives in a fresh context, and writes prioritized PR comments.\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: PULL REQUEST (diff or link)\n    - id: splitter\n      type: orchestrator\n      label: SPLIT\n      model: sonnet\n      tools:\n        - Read\n    - id: review_security\n      type: worker\n      label: Security & Auth\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: review_performance\n      type: worker\n      label: Performance & Memory\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: review_architecture\n      type: worker\n      label: Architecture & Style\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: review_tests\n      type: worker\n      label: Test Coverage\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: verifier\n      type: verifier\n      label: VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: Every kept finding points at a file and line in the diff.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: FINAL ANSWER\n      model: sonnet\n      tools:\n        - Read\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - review_security\n        - review_performance\n        - review_architecture\n        - review_tests\n      contract: subtask_json\n    - from:\n        - review_security\n        - review_performance\n        - review_architecture\n        - review_tests\n      to: verifier\n      contract: review_findings\n    - from: verifier\n      to: merger\n      contract: verified_findings\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task.\n  review_findings:\n    format: markdown\n    description: A numbered list; every item has its evidence and a confidence of high, medium or low.\n  verified_findings:\n    format: markdown\n    description: Only the items that passed verification, then the rejected ones with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the review lead. Read the pull request and give each reviewer the files and concerns that matter for their specialty.\n\nInput:\n{{goal}}\n\nOutput strictly as JSON with one key per worker: `review_security`, `review_performance`, `review_architecture`, `review_tests`. Each value is the exact task for that worker.\n\n## @node: review_security\nReview ONLY for security: injection, authn/authz gaps, secrets, unsafe deserialization, SSRF, missing input validation.\n\nYour task: {{splitter.review_security}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: review_performance\nReview ONLY for performance: N+1 queries, unbounded loops or payloads, leaks, blocking calls on hot paths, missing caching.\n\nYour task: {{splitter.review_performance}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: review_architecture\nReview ONLY for architecture: layering violations, duplicated logic, naming, consistency with existing patterns in the codebase.\n\nYour task: {{splitter.review_architecture}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: review_tests\nReview ONLY test coverage: untested branches, missing edge cases, brittle or meaningless assertions.\n\nYour task: {{splitter.review_tests}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: verifier\nYou are an independent auditor. Re-check each finding against the diff itself and remove false positives.\n\nYou only see the raw worker outputs below, not their reasoning. Drop any claim without concrete evidence, merge duplicates, and mark what you rejected and why.\n\nOriginal input: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nWrite the final review as prioritized PR comments (blocking, should fix, nit). Each comment names the file and line and says what to change.\n\n{{verifier.output}}\n",
  "---\nname: rfc-discovery-graph\ndescription: Explores a proposal from four angles in parallel, red-teams unstated assumptions in a fresh context, and drafts an RFC.\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: PROPOSAL\n    - id: splitter\n      type: orchestrator\n      label: SPLIT\n      model: sonnet\n      tools:\n        - Read\n    - id: feasibility\n      type: worker\n      label: Feasibility Study\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - WebSearch\n        - WebFetch\n    - id: prior_art\n      type: worker\n      label: Prior Art\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - WebSearch\n        - WebFetch\n    - id: interface_design\n      type: worker\n      label: Interface / DX\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - WebSearch\n        - WebFetch\n    - id: failure_modes\n      type: worker\n      label: Failure Modes\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - WebSearch\n        - WebFetch\n    - id: verifier\n      type: verifier\n      label: VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: No kept claim rests on an unstated assumption.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: FINAL ANSWER\n      model: sonnet\n      tools:\n        - Read\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - feasibility\n        - prior_art\n        - interface_design\n        - failure_modes\n      contract: subtask_json\n    - from:\n        - feasibility\n        - prior_art\n        - interface_design\n        - failure_modes\n      to: verifier\n      contract: research_notes\n    - from: verifier\n      to: merger\n      contract: verified_notes\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task.\n  research_notes:\n    format: markdown\n    description: A numbered list; every item has its evidence and a confidence of high, medium or low.\n  verified_notes:\n    format: markdown\n    description: Only the items that passed verification, then the rejected ones with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the RFC editor. Turn the proposal into four focused research questions.\n\nInput:\n{{goal}}\n\nOutput strictly as JSON with one key per worker: `feasibility`, `prior_art`, `interface_design`, `failure_modes`. Each value is the exact task for that worker.\n\n## @node: feasibility\nAssess ONLY feasibility: effort, dependencies, migration path and the hardest technical risk.\n\nYour task: {{splitter.feasibility}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: prior_art\nSurvey ONLY prior art: existing tools, competitors and published approaches, with what each gets right and wrong.\n\nYour task: {{splitter.prior_art}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: interface_design\nDesign ONLY the interface: API or CLI shape, configuration, error messages and the first five minutes of use.\n\nYour task: {{splitter.interface_design}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: failure_modes\nFind ONLY failure modes: what breaks at scale, under bad input, during partial rollout or rollback.\n\nYour task: {{splitter.failure_modes}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: verifier\nYou are a red-team reviewer. List the unstated assumptions behind each claim and reject claims that rest on them.\n\nYou only see the raw worker outputs below, not their reasoning. Drop any claim without concrete evidence, merge duplicates, and mark what you rejected and why.\n\nOriginal input: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nWrite a production RFC in Markdown: Summary, Motivation, Proposal, Alternatives considered, Risks, Open questions.\n\n{{verifier.output}}\n",
  "---\nname: bug-triaging-graph\ndescription: Triages a bug report with four parallel investigators, re-checks the evidence in a fresh context, and writes a root-cause diagnosis with a test plan.\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: BUG REPORT\n    - id: splitter\n      type: orchestrator\n      label: SPLIT\n      model: sonnet\n      tools:\n        - Read\n    - id: stack_trace\n      type: worker\n      label: Stack Trace Analyzer\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: logs_metrics\n      type: worker\n      label: Log / Metric Correlator\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: commits\n      type: worker\n      label: Commit Inspector\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: repro\n      type: worker\n      label: Minimal Repro Builder\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: verifier\n      type: verifier\n      label: VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: At least one hypothesis is connected to the symptom by evidence, and the repro reproduces it.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: FINAL ANSWER\n      model: sonnet\n      tools:\n        - Read\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - stack_trace\n        - logs_metrics\n        - commits\n        - repro\n      contract: subtask_json\n    - from:\n        - stack_trace\n        - logs_metrics\n        - commits\n        - repro\n      to: verifier\n      contract: hypotheses\n    - from: verifier\n      to: merger\n      contract: root_cause\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task.\n  hypotheses:\n    format: markdown\n    description: A numbered list; every item has its evidence and a confidence of high, medium or low.\n  root_cause:\n    format: markdown\n    description: Only the items that passed verification, then the rejected ones with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the triage lead. Split the bug report into four investigation tasks.\n\nInput:\n{{goal}}\n\nOutput strictly as JSON with one key per worker: `stack_trace`, `logs_metrics`, `commits`, `repro`. Each value is the exact task for that worker.\n\n## @node: stack_trace\nAnalyze ONLY the stack trace and error: the failing frame, the inputs that reach it, and why it throws.\n\nYour task: {{splitter.stack_trace}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: logs_metrics\nCorrelate ONLY logs and metrics: when it started, what changed at that time, and which users or requests are affected.\n\nYour task: {{splitter.logs_metrics}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: commits\nInspect ONLY recent commits and config changes that touch the failing path, and rank them by likelihood.\n\nYour task: {{splitter.commits}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: repro\nBuild ONLY a minimal reproduction: the smallest steps or script that trigger the bug.\n\nYour task: {{splitter.repro}}\n\nReturn findings as a numbered list. For each one give the evidence (file, line, quote or source) and a confidence of high, medium or low.\n\n## @node: verifier\nYou are an independent debugger. Check that the evidence actually connects each hypothesis to the symptom; reject the rest.\n\nYou only see the raw worker outputs below, not their reasoning. Drop any claim without concrete evidence, merge duplicates, and mark what you rejected and why.\n\nOriginal input: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nWrite the diagnosis: root cause, evidence, fix, and a test plan that reproduces the bug before the fix and passes after it.\n\n{{verifier.output}}\n",
  "---\nname: research-report\ndescription: Researches a question from four angles in parallel, fact-checks every claim against its source in a fresh context, and writes a sourced report.\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: RESEARCH QUESTION\n    - id: splitter\n      type: orchestrator\n      label: SPLIT\n      model: sonnet\n      tools:\n        - Read\n    - id: sources\n      type: worker\n      label: Primary Sources\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: figures\n      type: worker\n      label: Figures & Data\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: counterpoints\n      type: worker\n      label: Counterpoints\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: open_questions\n      type: worker\n      label: Open Questions\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: verifier\n      type: verifier\n      label: VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: Every kept claim names a source that says it, and every figure has a date.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: FINAL ANSWER\n      model: sonnet\n      tools:\n        - Read\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - sources\n        - figures\n        - counterpoints\n        - open_questions\n      contract: subtask_json\n    - from:\n        - sources\n        - figures\n        - counterpoints\n        - open_questions\n      to: verifier\n      contract: research_findings\n    - from: verifier\n      to: merger\n      contract: checked_findings\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task.\n  research_findings:\n    format: markdown\n    description: A numbered list of claims; every claim has its source, a short quote and a confidence of high, medium or low.\n  checked_findings:\n    format: markdown\n    description: Only the claims a cited source supports, then the rejected claims with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the research lead. Turn the question into four research tasks, one per angle, each saying what to look for and how recent it must be.\n\nInput:\n{{goal}}\n\nOutput strictly as JSON with one key per worker: `sources`, `figures`, `counterpoints`, `open_questions`. Each value is the exact task for that worker.\n\n## @node: sources\nFind ONLY primary sources: official documents, papers, datasets and first-hand accounts, with what each one says.\n\nYour task: {{splitter.sources}}\n\nReturn findings as a numbered list. For each one give the source (title and URL), what it says in a short quote, and a confidence of high, medium or low.\n\n## @node: figures\nCollect ONLY figures: statistics, dates, prices and measurements, each with where it comes from and how recent it is.\n\nYour task: {{splitter.figures}}\n\nReturn findings as a numbered list. For each one give the source (title and URL), what it says in a short quote, and a confidence of high, medium or low.\n\n## @node: counterpoints\nLook ONLY for disagreement: credible sources that contradict the obvious answer, and the reasons they give.\n\nYour task: {{splitter.counterpoints}}\n\nReturn findings as a numbered list. For each one give the source (title and URL), what it says in a short quote, and a confidence of high, medium or low.\n\n## @node: open_questions\nFind ONLY what is unknown or disputed: gaps in the evidence and claims that nobody has checked.\n\nYour task: {{splitter.open_questions}}\n\nReturn findings as a numbered list. For each one give the source (title and URL), what it says in a short quote, and a confidence of high, medium or low.\n\n## @node: verifier\nYou are a fact-checker. Check each claim against the source it cites; reject claims whose source does not say it or is not named.\n\nYou only see the raw worker outputs below, not their reasoning. Drop any claim without concrete evidence, merge duplicates, and mark what you rejected and why.\n\nOriginal input: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nWrite the research report in Markdown: the answer in two sentences, Key findings with their sources, Where sources disagree, Open questions, and a list of Sources.\n\n{{verifier.output}}\n",
  "---\nname: write-an-article\ndescription: Plans an article, post or newsletter from four angles in parallel, has an editor check the notes in a fresh context, and writes the draft.\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: BRIEF (topic, audience, length, voice)\n    - id: splitter\n      type: orchestrator\n      label: SPLIT\n      model: sonnet\n      tools:\n        - Read\n    - id: angle\n      type: worker\n      label: Angle & Headline\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: outline\n      type: worker\n      label: Outline\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: facts\n      type: worker\n      label: Facts & Quotes\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: reader\n      type: worker\n      label: Reader\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n        - WebFetch\n    - id: verifier\n      type: verifier\n      label: VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: Every fact kept has a source, and the angle and outline match the brief's audience and length.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: FINAL ANSWER\n      model: sonnet\n      tools:\n        - Read\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - angle\n        - outline\n        - facts\n        - reader\n      contract: subtask_json\n    - from:\n        - angle\n        - outline\n        - facts\n        - reader\n      to: verifier\n      contract: content_notes\n    - from: verifier\n      to: merger\n      contract: approved_notes\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task.\n  content_notes:\n    format: markdown\n    description: A numbered list of notes, each marked with its source or as opinion.\n  approved_notes:\n    format: markdown\n    description: The notes that passed the edit, then the cut ones with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the managing editor. Read the brief and give each writer the part of the piece they prepare, with the audience and length in mind.\n\nInput:\n{{goal}}\n\nOutput strictly as JSON with one key per worker: `angle`, `outline`, `facts`, `reader`. Each value is the exact task for that worker.\n\n## @node: angle\nWork ONLY on the angle: three possible headlines with a hook for each, and which one fits the audience best and why.\n\nYour task: {{splitter.angle}}\n\nReturn your notes as a numbered list. Mark each note with the source it rests on, or with \"opinion\" when it rests on none.\n\n## @node: outline\nWrite ONLY the outline: the sections in order, the point of each one, and where examples go.\n\nYour task: {{splitter.outline}}\n\nReturn your notes as a numbered list. Mark each note with the source it rests on, or with \"opinion\" when it rests on none.\n\n## @node: facts\nGather ONLY the facts the piece needs: claims, figures and quotes, each with its source.\n\nYour task: {{splitter.facts}}\n\nReturn your notes as a numbered list. Mark each note with the source it rests on, or with \"opinion\" when it rests on none.\n\n## @node: reader\nThink ONLY about the reader: what they already know, the questions they will ask, and the jargon to avoid.\n\nYour task: {{splitter.reader}}\n\nReturn your notes as a numbered list. Mark each note with the source it rests on, or with \"opinion\" when it rests on none.\n\n## @node: verifier\nYou are the editor. Check each note for accuracy and for fit with the brief.\n\nYou only see the raw worker outputs below, not their reasoning. Cut every factual note without a source and every note off the brief, merge duplicates, and list what you cut and why.\n\nOriginal input: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nWrite the piece from the approved notes: the headline, a hook paragraph, the sections of the outline, and a closing line. Use only facts from the notes, in the voice and length the brief asks for.\n\n{{verifier.output}}\n",
  "---\nname: analyze-a-dataset\ndescription: \"Analyzes a CSV or table: profiling, cleaning rules, answers and sanity checks run in parallel, every figure is re-checked in a fresh context, then a data report.\"\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: DATA FILE + QUESTIONS\n    - id: splitter\n      type: orchestrator\n      label: SPLIT\n      model: sonnet\n      tools:\n        - Read\n    - id: profile\n      type: worker\n      label: Profile\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: cleaning\n      type: worker\n      label: Cleaning Rules\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: analysis\n      type: worker\n      label: Analysis\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: sanity\n      type: worker\n      label: Sanity Checks\n      model: haiku\n      tools:\n        - Read\n        - Grep\n        - Glob\n        - Bash\n    - id: verifier\n      type: verifier\n      label: VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: Every kept figure says how it was computed and matches the data on a spot check.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: FINAL ANSWER\n      model: sonnet\n      tools:\n        - Read\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - profile\n        - cleaning\n        - analysis\n        - sanity\n      contract: subtask_json\n    - from:\n        - profile\n        - cleaning\n        - analysis\n        - sanity\n      to: verifier\n      contract: data_findings\n    - from: verifier\n      to: merger\n      contract: checked_figures\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task.\n  data_findings:\n    format: markdown\n    description: A numbered list; every figure has how it was computed and a confidence of high, medium or low.\n  checked_figures:\n    format: markdown\n    description: Only the figures that matched the data on a spot check, then the rejected ones with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the analysis lead. Read the file path and the questions, and give each analyst their part of the work on that file.\n\nInput:\n{{goal}}\n\nOutput strictly as JSON with one key per worker: `profile`, `cleaning`, `analysis`, `sanity`. Each value is the exact task for that worker.\n\n## @node: profile\nProfile ONLY the data: columns, types, row count, missing values, duplicates and outliers. Compute every figure; never estimate it.\n\nYour task: {{splitter.profile}}\n\nReturn findings as a numbered list. For each one give the figure, how you got it (the command, formula or rows it rests on) and a confidence of high, medium or low. Never change the data file.\n\n## @node: cleaning\nPropose ONLY cleaning rules: how to fix types, missing values, duplicates and bad rows, with how many rows each rule touches.\n\nYour task: {{splitter.cleaning}}\n\nReturn findings as a numbered list. For each one give the figure, how you got it (the command, formula or rows it rests on) and a confidence of high, medium or low. Never change the data file.\n\n## @node: analysis\nAnswer ONLY the questions in the task with the data: each figure, and the command or formula that produced it.\n\nYour task: {{splitter.analysis}}\n\nReturn findings as a numbered list. For each one give the figure, how you got it (the command, formula or rows it rests on) and a confidence of high, medium or low. Never change the data file.\n\n## @node: sanity\nCheck ONLY whether the data can be trusted: totals that should add up, impossible values, and gaps in time or coverage.\n\nYour task: {{splitter.sanity}}\n\nReturn findings as a numbered list. For each one give the figure, how you got it (the command, formula or rows it rests on) and a confidence of high, medium or low. Never change the data file.\n\n## @node: verifier\nYou are a data reviewer. Spot-check each figure against the file itself; reject figures you cannot trace back to the data.\n\nYou only see the raw worker outputs below, not their reasoning. Drop any claim without concrete evidence, merge duplicates, and mark what you rejected and why.\n\nOriginal input: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nWrite the data report: the answers with their figures, the cleaning steps to apply in order, and the caveats a reader must know.\n\n{{verifier.output}}\n",
  "---\nname: design-an-app\ndescription: \"Designs an app from an idea: users, scope, screens and data model in parallel, a fresh-context product review that makes them fit together, then a product spec.\"\nspec: skill-graph/1\ntopology:\n  nodes:\n    - id: goal\n      type: input\n      label: APP IDEA\n    - id: splitter\n      type: orchestrator\n      label: SPLIT\n      model: sonnet\n      tools:\n        - Read\n    - id: users\n      type: worker\n      label: Users & Stories\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n    - id: features\n      type: worker\n      label: Features & Scope\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n    - id: screens\n      type: worker\n      label: Screens & Flows\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n    - id: data_model\n      type: worker\n      label: Data Model\n      model: haiku\n      tools:\n        - Read\n        - WebSearch\n    - id: verifier\n      type: verifier\n      label: VERIFIER (Fresh Context)\n      isolated_context: true\n      model: opus\n      tools:\n        - Read\n        - Grep\n        - Glob\n      gate: Every first-version feature maps to a user story, a screen and the data it needs.\n      on_fail: retry\n      max_retries: 1\n    - id: merger\n      type: synthesizer\n      label: FINAL ANSWER\n      model: sonnet\n      tools:\n        - Read\n  edges:\n    - from: goal\n      to: splitter\n    - from: splitter\n      to:\n        - users\n        - features\n        - screens\n        - data_model\n      contract: subtask_json\n    - from:\n        - users\n        - features\n        - screens\n        - data_model\n      to: verifier\n      contract: design_proposals\n    - from: verifier\n      to: merger\n      contract: approved_design\ncontracts:\n  subtask_json:\n    format: json\n    description: One key per worker id; each value is that worker's task.\n  design_proposals:\n    format: markdown\n    description: A numbered list of proposals, each with the user need it serves and a confidence of high, medium or low.\n  approved_design:\n    format: markdown\n    description: The proposals that fit together, then the cut ones with the reason.\n---\n\n# Node Prompts & Edge Contracts\n\n## @node: splitter\nYou are the product lead. Read the idea and give each designer their part of the app, with the constraints the idea states.\n\nInput:\n{{goal}}\n\nOutput strictly as JSON with one key per worker: `users`, `features`, `screens`, `data_model`. Each value is the exact task for that worker.\n\n## @node: users\nWork ONLY on users: who they are, the jobs they need the app for, and the three most important user stories.\n\nYour task: {{splitter.users}}\n\nReturn your proposals as a numbered list. For each one give the user need it serves and a confidence of high, medium or low.\n\n## @node: features\nScope ONLY the features: the smallest useful first version, what waits for later, and why.\n\nYour task: {{splitter.features}}\n\nReturn your proposals as a numbered list. For each one give the user need it serves and a confidence of high, medium or low.\n\n## @node: screens\nDesign ONLY the screens and flows: each screen, what it shows, and how the user moves between them, with empty and error states.\n\nYour task: {{splitter.screens}}\n\nReturn your proposals as a numbered list. For each one give the user need it serves and a confidence of high, medium or low.\n\n## @node: data_model\nDesign ONLY the data: entities, fields and relationships, and the outside services the app needs.\n\nYour task: {{splitter.data_model}}\n\nReturn your proposals as a numbered list. For each one give the user need it serves and a confidence of high, medium or low.\n\n## @node: verifier\nYou are a product reviewer. Check that the proposals fit together: every screen serves a user story, every feature has a screen, and the data model holds what the screens show.\n\nYou only see the raw worker outputs below, not their reasoning. Cut proposals that serve no stated user need, settle conflicts between them, and list what you cut and why.\n\nOriginal input: {{goal}}\n\nWorker outputs:\n{{workers.output}}\n\n## @node: merger\nWrite the product spec in Markdown: Problem, Users and stories, First version scope, Screens and flows, Data model, Open questions.\n\n{{verifier.output}}\n",
];

export const SHARE_DICTIONARIES: readonly string[] = [GENERAL, ...STARTERS.map((starter) => `${GENERAL}
${starter}`.slice(-SHARE_DICTIONARY_WINDOW))];
